index 50ed8f0..c499fa2 100644
--- a/io/io.cpp
+++ b/io/io.cpp
@@ -416,6 +416,19 @@ extern "C" int c_bufcache_status(natl *blocks, natl *io_count)
 //   ESAME 2023-01-11 )

 // ( SOLUZIONE 2023-01-11
+
+static void bufcache_init()
+{
+	des_ata *d = &hard_disk;
+	for (int i = 0; i < MAX_BUF_DES; i++) {
+		d->bufcache[i].full = false;
+		d->bufcache[i].next = (i + 1 < MAX_BUF_DES) ? i + 1 : -1;
+		d->bufcache[i].prev = (i - 1 >= 0) ? i - 1 : -1;
+	}
+	d->lru = 0;
+	d->mru = MAX_BUF_DES - 1;
+}
+
 //   SOLUZIONE 2023-01-11 )
 /// Piedino dell'APIC per le richieste di interruzione dell'hard disk
 const natb HD_IRQ = 14;
@@ -495,6 +508,37 @@ extern "C" void c_readhd_n(natb vetti[], natl primo, natb quanti)

 /// @todo Gestire l'operazione tenendo conto della buffer cache.
 // ( SOLUZIONE 2023-01-11
+	sem_wait(d->mutex);
+
+	int b = -1;
+	for (int i = 0; i < MAX_BUF_DES; i++) {
+		if (d->bufcache[i].full && d->bufcache[i].block == primo) {
+			b = i;
+			break;
+		}
+	}
+
+	if (b >= 0) {
+		memcpy(vetti, d->bufcache[b].buf, DIM_BLOCK * quanti);
+		bufcache_promote(&d->bufcache[b]);
+		sem_signal(d->mutex);
+		return;
+	}
+
+	int idx = d->lru;
+	if (d->bufcache[idx].full) {
+		d->bufcache[idx].full = false;
+	}
+	d->bufcache[idx].block = primo;
+	d->bufcache[idx].full = true;
+
+	starthd_in(d, d->bufcache[idx].buf, primo, quanti);
+	sem_wait(d->sincr);
+
+	memcpy(vetti, d->bufcache[idx].buf, DIM_BLOCK * quanti);
+	bufcache_promote(&d->bufcache[idx]);
+
+	sem_signal(d->mutex);
 //   SOLUZIONE 2023-01-11 )
 //   ESAME 2023-01-11 ]
 }
