 /// @todo Gestire l'operazione tenendo conto della buffer cache.
 // ( SOLUZIONE 2023-01-11
+	sem_wait(d->mutex);
+
+	int b = -1;
+	for (int i = 0; i < MAX_BUF_DES; i++) {
+		if (d->bufcache[i].full && d->bufcache[i].block == primo) {
+			b = i;
+			break;
+		}
+	}
+
+	if (b >= 0) {
+		memcpy(d->bufcache[b].buf, vetto, DIM_BLOCK * quanti);
+		starthd_out(d, d->bufcache[b].buf, primo, quanti);
+		sem_wait(d->sincr);
+		bufcache_promote(&d->bufcache[b]);
+		sem_signal(d->mutex);
+		return;
+	}
+
+	starthd_out(d, vetto, primo, quanti);
+	sem_wait(d->sincr);
+
+	sem_signal(d->mutex);
 //   SOLUZIONE 2023-01-11 )
 //   ESAME 2023-01-11 ]
 }
@@ -735,6 +802,7 @@ bool hd_init()
 	hd::enable_intr();

 // ( SOLUZIONE 2023-01-11
+	bufcache_init();
 //   SOLUZIONE 2023-01-11 )

 	return true;
